function renderSettings(cnic){if(cnic!==undefined)user.privateCnic=cnic;const phone=user.phone||'',code=[...countryChoices].sort((a,b)=>b[0].length-a[0].length).find(([c])=>phone.startsWith(c))?.[0]||'+92';$('#account-content').innerHTML=`<div class="panel"><h2>Account settings</h2>${errorBox()}<form id="settings-form">${input('fullName','Full name','text',`value="${esc(user.fullName)}" maxlength="120"`)}<div class="field"><label for="settings-email">Email ID (cannot be changed)</label><input id="settings-email" value="${esc(user.email)}" readonly></div><div class="field"><label for="settings-cnic">CNIC (cannot be changed)</label><input id="settings-cnic" value="${esc(user.privateCnic||'')}" readonly></div><div class="field"><label for="settings-code">Country calling code</label><select name="countryCode" id="settings-code">${countryChoices.map(([c,n])=>`<option value="${c}" ${c===code?'selected':''}>${esc(n)} (${c})</option>`).join('')}</select></div>${input('mobile','Mobile number','tel',`value="${esc(phone.slice(code.length))}"`)}${user.googleAccount?'':passwordField('currentPassword','Current password',false)+passwordField('password','New password (optional, at least 8 characters)',false)+passwordField('confirmPassword','Confirm new password',false)}<button class="btn btn-black" type="submit">Save account settings</button></form></div><div class="panel danger-zone"><h2>Delete account permanently</h2><p>This removes your personal profile and access permanently. Anonymous transaction identifiers remain for record integrity. Active commitments must be closed first.</p><form id="delete-form">${user.hasPassword&&!user.googleAccount?passwordField('deletePassword','Current password'):''}${input('confirm','Type DELETE to confirm')}<button class="btn btn-danger" type="submit">Delete my account</button></form></div>`;bindPasswords();$('#settings-form').onsubmit=async e=>{e.preventDefault();pending(e.target,true);try{const privateCnic=user.privateCnic;user=(await api('/api/auth/settings',Object.fromEntries(new FormData(e.target)))).user;user.privateCnic=privateCnic;toast('Account settings saved.');renderSettings()}catch(err){setError(err.message);pending(e.target,false)}};$('#delete-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));confirmAction('Permanently delete account?','This cannot be undone.',async()=>{await api('/api/auth/delete',{confirm:data.confirm,currentPassword:data.deletePassword});user=null;updateNav();navigate('/');toast('Your account has been deleted.')})}}
function officeText(){const c=siteContent.settings?.contact||{};return `Please visit the AuctionHouse.pk office ${c.hours||'during office working hours'} to finalize the documentation. ${c.address||''}`}
async function syncNotifications(showNew=true){if(!user||noticeSync)return;noticeSync=true;try{const r=await api('/api/notifications?after='+(noticesInitialized?noticeCursor:0));if(showNew&&noticesInitialized)for(const n of [...r.notifications].reverse().filter(n=>n.kind!=='bid_received')){const key=n.kind==='bid'?'bid:'+n.listing_id:'notice:'+n.id;let el=$$('#notification-toasts .bid-notification').find(e=>e.dataset.noticeKey===key);if(!el){el=document.createElement('a');el.className='bid-notification';el.dataset.noticeKey=key;el.dataset.count='0';$('#notification-toasts').append(el)}const count=Number(el.dataset.count)+1;el.dataset.count=String(count);el.href=n.url;el.innerHTML=`<strong>${esc(n.title)}</strong><span>${n.kind==='bid'&&count>1?count+' new bids, latest '+esc(n.body.replace('New bid: ','')):esc(n.body)}</span><small>${siteDate(n.created_at,true)}</small><button type="button" aria-label="Dismiss notification">×</button>`;$('button',el).onclick=e=>{e.preventDefault();e.stopPropagation();el.remove()};clearTimeout(el.dismissTimer);el.dismissTimer=setTimeout(()=>el.remove(),12000)}noticeCursor=Math.max(noticeCursor,...r.notifications.map(n=>n.id),0);noticesInitialized=true;$$('[data-notification-count]').forEach(el=>el.textContent=r.unread?String(r.unread):'');if(location.pathname==='/notifications'&&r.notifications.length)await notificationsPage(routeRun,false)}catch{}finally{noticeSync=false}}
function connectLive(listingId){if(liveSource)liveSource.close();if(!user&&!listingId)return;const channels=[...(listingId?[listingId]:[]),...(user?[null]:[])],connections=[],timers=[];let closed=false;const refresh=async id=>{try{if(id&&currentListingRefresh)await currentListingRefresh();if(!id)await syncNotifications(true)}catch{}};for(const id of channels){const connect=()=>{if(closed)return;const socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/api/live'+(id?'?listing='+encodeURIComponent(id):''));connections.push(socket);socket.onmessage=e=>{if(e.data==='pong')return;refresh(id)};socket.onclose=()=>{if(!closed)timers.push(setTimeout(connect,4000+Math.random()*2000))};socket.onerror=()=>socket.close()};connect()}liveSource={close(){closed=true;connections.forEach(s=>{s.onclose=null;s.close()});timers.forEach(clearTimeout)}}}
async function notificationsPage(run,mark=true){if(!authGate('/notifications'))return;const r=await api('/api/notifications');if(run!==routeRun)return;$('#app').innerHTML=pageTop('Notifications','')+`<section class="section notifications-list">${r.notifications.length?r.notifications.map(n=>`<a class="panel notification-item ${n.read_at?'':'unread'}" href="${esc(n.url)}"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${siteDate(n.created_at,true)}</small><small>Email: ${n.email_status==='sent'?'sent':'queued for delivery'}</small></a>`).join(''):'<div class="panel">No notifications yet.</div>'}</section>`;if(mark&&r.notifications.length){await api('/api/notifications',{before:Math.max(...r.notifications.map(n=>n.id))});$$('[data-notification-count]').forEach(el=>el.textContent='')}}

