async function api(path,data){const response=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let json;try{json=await response.json()}catch{throw new Error('Could not connect. Please try again.')}if(!response.ok)throw new Error(json.error||'Please try again.');return json}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function setError(text){const el=$('#form-error');if(el){el.textContent=text;el.hidden=false;el.scrollIntoView({block:'nearest',behavior:'smooth'})}else toast(text)}
function pending(form,active){const b=$('button[type="submit"]',form);if(!b)return;b.disabled=active;b.setAttribute('aria-busy',String(active));if(active){b.dataset.label=b.innerHTML;b.textContent='Please wait…'}else if(b.dataset.label)b.innerHTML=b.dataset.label}
function errorBox(){return '<div id="form-error" class="form-error" role="alert" hidden></div>'}
$('#menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('header').classList.toggle('menu-open',open);$('#menu').setAttribute('aria-expanded',String(open))};$('#dialog-close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};
function updateNav(){const a=$('.nav-actions .login-nav');a.href=user?'/logout':'/login';a.textContent=user?'Log out':'Log in';$('.notification-nav').setAttribute('aria-label','Notifications');a.classList.toggle('logged-in',!!user);$('.nav-actions .account-nav').hidden=!user;$('.notification-nav').hidden=!user;$('.nav-actions .register-nav').hidden=!!user;$$('header a').forEach(el=>{const path=new URL(el.href,location.origin).pathname,active=path===location.pathname;el.classList.toggle('nav-current',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});const links=$('.mobile-account-links');if(links)links.innerHTML=$$('.nav-actions>.account-nav,.nav-actions>.login-nav,.nav-actions>.register-nav').filter(el=>!el.hidden).map(el=>el.outerHTML).join('');const contact=siteContent.settings.contact;if(contact?.phone){const phone=contact.phone.replace(/[^0-9]/g,'');if(phone.length>=8)$('.whatsapp-float').href='https://wa.me/'+phone}}
function pageTop(title,description=''){return `<section class="page-top"><h1>${title}</h1>${description?'<p>'+description+'</p>':''}</section>`}
function projectCard(p){return `<article class="project-card"><a class="project-art" href="/marketplace?project=${encodeURIComponent(p.id)}"><img src="${esc(p.images[0]||'/assets/pine-axis.webp')}" ${posterSources(p.images[0]||'/assets/pine-axis.webp')} alt="${esc(p.name)}" loading="lazy" width="640" height="800"></a><div class="project-body"><div class="project-head"><div><h3>${esc(p.name)}</h3><p>${esc(p.scheme)}, Lahore</p></div></div><div class="project-specs"><div><small>Plot categories</small><strong>${p.categories.map(c=>esc(c.category)).join(', ')}</strong></div><div><small>Instalment plan</small><strong>${esc(p.instalments)}</strong></div><div><small>Sale Method</small><strong>${esc(p.sale_method)}</strong></div></div></div><div class="project-card-bottom"><a href="/marketplace?project=${encodeURIComponent(p.id)}">View project listings ↗</a></div></article>`}
function home(){const page={heading:'Where luck meets opportunity…',intro:'Compete in the open auction or negotiate on your terms.',...siteContent.settings.page},ps=siteContent.projects.filter(p=>p.home_visible).sort((a,b)=>a.home_order-b.home_order);$('#app').innerHTML=`<section class="hero"><div class="hero-inner"><div class="hero-copy"><h1>${esc(page.heading)}</h1><p>${esc(page.intro)}</p>${page.banner&&page.deadline>Date.now()?`<div class="deadline-block" data-banner-deadline="${page.deadline}"><p>${esc(page.banner)}<br><strong>${siteDate(page.deadline,true)}</strong></p></div>`:''}<div class="btn-row"><a href="/marketplace" class="btn btn-black">Explore Marketplace ↗</a><a href="/sell" class="btn btn-outline">Sell now ↗</a></div></div><div class="hero-preview">${ps.slice(0,2).map(p=>`<a href="/marketplace?project=${encodeURIComponent(p.id)}"><img src="${esc(p.images[0])}" alt="${esc(p.name)}" width="480" height="600" loading="lazy"><strong>${esc(p.name)}</strong></a>`).join('')}</div></div></section><section class="section"><div class="section-head"><div><h2>Explore Active projects of LDA.</h2><p>Explore commercial and residential opportunities in Lahore.</p></div></div><div class="project-grid">${ps.map(projectCard).join('')}</div></section><section class="section"><div class="launch-card"><div><h2>The right property.<br>The right connection.</h2><p>Explore listings, save your favourites or submit a property for review.</p></div><a href="/marketplace" class="btn btn-lime">Explore Marketplace ↗</a></div></section>`;startClocks()}
