function input(name,label,type='text',options=''){return `<div class="field"><label for="a-${name}">${label}</label><input id="a-${name}" name="${name}" type="${type}" required ${options}></div>`}
function passwordField(name,label,required=true){return `<div class="field"><label for="a-${name}">${label}</label><div class="password-wrap"><input id="a-${name}" name="${name}" type="password" ${required?'required':''} minlength="8" autocomplete="${name==='loginPassword'?'current-password':'new-password'}"><button type="button" data-toggle="a-${name}" aria-label="Show ${label.toLowerCase()}">◉</button></div>${name==='password'?'<small>At least 8 characters.</small>':''}</div>`}
function googleButton(next){return `<a class="google-button" href="/api/google/start?returnTo=${encodeURIComponent(next)}"><span class="google-g" aria-hidden="true">G</span> Continue with Google</a>`}
function bindPasswords(){$$('[data-toggle]').forEach(b=>b.onclick=()=>{const i=$('#'+b.dataset.toggle),show=i.type==='password';i.type=show?'text':'password';b.setAttribute('aria-label',(show?'Hide':'Show')+' password')});const password=$('#a-password'),confirm=$('#a-confirmPassword');if(password&&confirm){const check=()=>confirm.setCustomValidity(confirm.value&&password.value!==confirm.value?'Passwords do not match.':'');password.oninput=check;confirm.oninput=check}}
function profileFields(complete=false){return `<div class="form-grid">${input('fullName','Full name','text','autocomplete="name" maxlength="120" ')}${input('fatherName',"Father’s name",'text','autocomplete="off" maxlength="120" ')}${input('cnic','CNIC number','text','inputmode="numeric" placeholder="12345-1234567-1" pattern="[1-7][0-9]{4}-?[0-9]{7}-?[0-9]" maxlength="15" autocomplete="off"')}${input('email','Email address','email',`autocomplete="email" maxlength="254" ${complete?'readonly':''}`)}<div class="field full"><label for="a-mobile">Mobile number</label><div class="phone-input"><select id="a-countryCode" name="countryCode" aria-label="Country calling code">${countryChoices.map(([c,n])=>`<option value="${c}">${n} (${c})</option>`).join('')}</select><input id="a-mobile" name="mobile" type="tel" inputmode="tel" placeholder="300 1234567" autocomplete="tel-national" required maxlength="20"></div><small>Choose a country code, then enter your mobile number.</small></div><div class="field full"><label for="a-address">Current address</label><textarea id="a-address" name="address" required  maxlength="600" autocomplete="street-address" placeholder="Street, locality, city, postal code and country"></textarea></div>${complete&&!user.hasPassword?'':passwordField('password',complete?'Password (optional)':'Password',!complete)+passwordField('confirmPassword','Confirm password',!complete)}</div>`}
function authPage(kind,q){const next=safeNext(q);if(user&&kind!=='complete-profile'){navigate(user.profileComplete?next:'/complete-profile?returnTo='+encodeURIComponent(next));return}const complete=kind==='complete-profile',register=kind==='register'||complete;if(complete&&!user){loginRequired('/complete-profile');return}$('#app').innerHTML=pageTop(register?(complete?'One last step.<br>Make it your account.':'Your next chapter.<br>Your own account.'):'Welcome back.<br>Your next move awaits.',register?'Create your AuctionHouse.pk account to buy, sell and connect.':'Log in to bid, save favourites and manage your listings.',register?'Create account':'Log in',register?'GET STARTED':'WELCOME TO AUCTIONHOUSE.PK')+`<section class="section auth-layout"><aside class="auth-aside"><div class="auth-illustration" aria-hidden="true"><span>✳</span><i>↗</i></div><h2>Two projects.<br>One place to connect.</h2><p>Your buying interests, selling plans and next opportunities, together in one account.</p><div class="auth-project-pills"><span>Pine Axis</span><span>Pine Executive</span></div></aside><div class="panel auth-panel"><div class="auth-switch"><a class="${!register?'active':''}" href="/login?returnTo=${encodeURIComponent(next)}">Log in</a><a class="${register?'active':''}" href="/register?returnTo=${encodeURIComponent(next)}">Create account</a></div>${!complete?googleButton(next)+'<div class="auth-divider"><span>or continue with email</span></div>':''}${errorBox()}<form id="auth-form">${register?profileFields(complete):input('email','Email address','email','autocomplete="email"')+passwordField('loginPassword','Password')}<div class="auth-form-foot">${!register?'<label class="show-label">Your session stays signed in securely.</label><a href="/forgot-password">Forgot password?</a>':'<span>All fields are required unless marked optional.</span>'}</div><button class="btn btn-black full-button" type="submit">${register?complete?'Complete my account':'Create my account':'Log in'} <span>↗</span></button></form></div></section>`;if(q.get('error'))setError(q.get('error'));if(complete){$('#a-fullName').value=user.fullName||'';$('#a-email').value=user.email||''}bindPasswords();$('#a-cnic')?.addEventListener('input',e=>{const digits=e.target.value.replace(/\D/g,'').slice(0,13);e.target.value=digits.length>12?digits.slice(0,5)+'-'+digits.slice(5,12)+'-'+digits.slice(12):digits.length>5?digits.slice(0,5)+'-'+digits.slice(5):digits});$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.target;pending(form,true);try{const data=Object.fromEntries(new FormData(form));if(!register)data.password=data.loginPassword;const result=await api('/api/auth/'+(complete?'profile':register?'register':'login'),data);user=result.user;updateNav();navigate(user.profileComplete?next:'/complete-profile?returnTo='+encodeURIComponent(next));toast(register?'Your account is ready.':'Welcome back.')}catch(error){setError(error.message);pending(form,false)}}}
function recoveryPage(reset,q){$('#app').innerHTML=pageTop(reset?'A fresh start.<br>A new password.':'Let’s get you<br>back in.','Recover access to your AuctionHouse.pk account.',reset?'Reset password':'Forgot password')+`<section class="section recovery-section"><div class="panel"><a href="/login" class="text-link">← Back to log in</a><h2>${reset?'Choose a new password.':'Forgot your password?'}</h2><p>${reset?'Use a strong password you haven’t used before.':'Enter your registered email address. We’ll send a link to reset your password.'}</p>${errorBox()}<form id="recovery-form">${reset?passwordField('password','New password')+passwordField('confirmPassword','Confirm password'):input('email','Registered email address','email','autocomplete="email"')}<button class="btn btn-black full-button" type="submit">${reset?'Reset password':'Send recovery link'} <span>↗</span></button></form></div></section>`;bindPasswords();$('#recovery-form').onsubmit=async e=>{e.preventDefault();const form=e.target;pending(form,true);try{const data=Object.fromEntries(new FormData(form));if(reset)data.token=q.get('token');const result=await api('/api/auth/'+(reset?'reset':'forgot'),data);$('.recovery-section .panel').innerHTML=`<div class="success"><span class="success-mark">✓</span><h2>${reset?'Password updated.':'Check your inbox.'}</h2><p>${esc(result.message)}</p><a href="/login" class="btn btn-black">Back to log in <span>↗</span></a></div>`;if(reset){user=null;updateNav()}}catch(error){setError(error.message);pending(form,false)}}}
function areaPage(){$('#app').innerHTML=pageTop('The area.<br>Without the guesswork.','1 Marla = 225 sq ft. One Kanal = 20 Marla = 4,500 sq ft.','Area converter')+`<section class="section calc-grid"><form id="area-form" class="panel"><h2>Convert your area.</h2>${['Kanal','Marla','Additional square feet'].map((label,i)=>`<div class="field"><label for="area-${i}">${label}</label><input id="area-${i}" type="number" min="0" step="0.01" value="${[1,5,100][i]}" required></div>`).join('')}<button class="btn btn-black" type="submit">Calculate area ↗</button></form><div class="result-box" aria-live="polite"><small>TOTAL AREA</small><h2 id="area-total">5,725 sq ft</h2><p id="area-yards">636.11 square yards</p><div class="spec-line"><span>1 Marla</span><strong>225 sq ft</strong></div><div class="spec-line"><span>1 Kanal</span><strong>4,500 sq ft</strong></div></div></section>`;const calculate=()=>{const vals=[0,1,2].map(i=>Number($('#area-'+i).value));if(vals.some(n=>!Number.isFinite(n)||n<0))return;const area=areaSft(...vals);$('#area-total').textContent=area.toLocaleString(undefined,{maximumFractionDigits:2})+' sq ft';$('#area-yards').textContent=(area/9).toLocaleString(undefined,{maximumFractionDigits:2})+' square yards'};$('#area-form').onsubmit=e=>{e.preventDefault();calculate()};$$('#area-form input').forEach(i=>i.oninput=calculate)}
function stepIllustration(i){const paths=['<circle cx="40" cy="40" r="23"/><path d="M57 57l23 23M25 40h30M40 25v30"/>','<circle cx="50" cy="29" r="14"/><path d="M22 80v-9a28 28 0 0156 0v9zM76 20l7 7 12-13"/>','<path d="M22 70h56v12H22zM37 22l20-9 18 40-20 9zM46 55L27 67M65 31l15-7"/>','<path d="M15 30h65l-15-15M85 70H20l15 15M80 30L65 45M20 70l15-15"/>','<path d="M12 48l38-32 38 32M23 43v40h54V43M42 83V58h17v25M65 21v16"/>','<path d="M15 83h70M25 83V24h50v59M18 24l32-13 32 13M36 36h7m14 0h7M36 48h7m14 0h7M43 83V63h14v20"/>'];return `<svg class="step-illustration" viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[i%paths.length]}</svg>`}
function howPage(){$('#app').innerHTML=pageTop('How it Works')+`<section class="section"><div class="steps">${(siteContent.settings.how||[]).map((step,i)=>`<article class="step">${stepIllustration(i)}<span class="step-num">${String(i+1).padStart(2,'0')}</span><h3>${esc(step.title)}</h3><p>${esc(step.body)}</p></article>`).join('')}</div><a class="btn btn-accent" href="/marketplace">Explore Marketplace</a></section>`}
function privacyPage(){$('#app').innerHTML=pageTop('Your information.<br>Handled with care.','Your account, listings, bids and saved favourites.','Privacy')+`<section class="section"><div class="prose"><h2>Your account information.</h2><p>Registration collects your name, father’s name, CNIC number, email, mobile number and current address. CNIC and address are encrypted before storage. Passwords are stored as secure hashes.</p><h2>Your saved interests.</h2><p>Your favourites, bids and seller listings are linked to your account. Public bids use a listing-specific bidding ID. Your CNIC, account address and contact details are not included in public account responses or bid history. Private negotiation history is visible only to its buyer and seller.</p><h2>Sign-in and recovery.</h2><p>Session cookies keep you signed in. Google sign-in requests your name and email; it does not request access to your Gmail inbox. Password recovery uses a time-limited email link.</p></div></section>`}
function notFound(){$('#app').innerHTML=pageTop('Your next move<br>is still ahead.','Find your next opportunity in the marketplace.','Page not found')+'<section class="section"><a href="/marketplace" class="btn btn-black">View marketplace ↗</a></section>'}
function feesPage(){$('#app').innerHTML=pageTop('Fees and participation','Transparent fees and Refundable Token Money.')+`<section class="section"><div class="panel prose"><h2>Service fee: 0.5% for each party.</h2><p>The buyer and seller each pay a service fee of 0.5% of the final total price of the plot. The closed deal records each party?s service fee separately. Per-unit accepted prices are converted to the total plot price before the fee is calculated.</p><h2>Refundable Token Money.</h2><p>The Refundable Token Money is configured by Auction House for the project or individual property. Your account needs sufficient available funds before participating or publishing a reviewed property. A token reservation remains separate from service fees and is released after the applicable review and documentation steps.</p><p>To refill your account, contact hello@auctionhouse.pk, call 0339-2828466, or visit the office during office working hours.</p><p>Previously issued agreements retain their accepted terms. Government taxes and third-party charges are separate.</p></div></section>`}
function managementContext(run){return {root:$('#app'),user,api,esc,pending,toast,loginRequired,pageTop,isCurrent:()=>run===routeRun}}
function aboutPage(){const sections=String(siteContent.settings.about||'').split(/\n\s*\n/),intro=sections.shift()||'';$('#app').innerHTML=pageTop('About us')+`<section class="section prose"><p>${esc(intro)}</p>${sections.map(section=>'<div>'+section.split('\n').filter(Boolean).map(line=>'<p>'+esc(line)+'</p>').join('')+'</div>').join('')}</section>`}
function contactPage(){const c=siteContent.settings.contact||{};$('#app').innerHTML=pageTop('Contact us')+`<section class="section contact-layout"><div class="panel"><h2>Visit or get in touch</h2><p><strong>Email ID</strong><br><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></p><p><strong>Whatsapp and Mobile number</strong><br><a href="tel:${esc(c.phone)}">${esc(c.phone)} (AUCTION)</a><br><a href="https://wa.me/${esc(String(c.phone||'').replace(/[^0-9]/g,''))}" target="_blank" rel="noopener">Message on WhatsApp</a></p><p><strong>Address</strong><br>${esc(c.address)}</p><p><a class="btn btn-outline" href="${esc(c.mapLink)}" target="_blank" rel="noopener">Open location in Google Maps</a></p></div><iframe class="office-map" title="AuctionHouse.pk office location" src="${esc(c.mapEmbed)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></section>`}
function logoutPrompt(){confirmAction('Log out?','Confirm you want to log out of AuctionHouse.pk.',async()=>{await api('/api/auth/logout',{});user=null;noticesInitialized=false;noticeCursor=0;if(liveSource)liveSource.close();updateNav();navigate('/')})}
function navigate(path,replace=false){if(path==='/logout'){logoutPrompt();return}if(path.startsWith('/budapest-admin')||path.startsWith('/admin')){location.assign(path.startsWith('/admin')?'/budapest-admin':path);return}history[replace?'replaceState':'pushState']({},'',path);return route()}
async function route(){const run=++routeRun,parts=location.pathname.split('/').filter(Boolean),q=new URLSearchParams(location.search);if(liveSource){liveSource.close();liveSource=null}clearInterval(auctionTimer);clearInterval(window.nov8Clock);clearTimeout(auctionPoll);currentListingRefresh=null;$('nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if($('#dialog').open)$('#dialog').close();try{switch(parts[0]){case undefined:home();break;case 'projects-info':projectInfoPage(parts[1]);break;case 'marketplace':case 'auctions':await marketPage(q,run);break;case 'listing':if(['axis','executive'].includes(parts[1])){navigate('/listing/AH-DEMO-'+(parts[1]==='axis'?'1001':'1002'),true);return}if(parts[2]==='negotiation')await negotiationPage(parts[1],parts[3],run);else await listingPage(parts[1],parts[2],run,q);break;case 'login':case 'register':case 'complete-profile':authPage(parts[0],q);break;case 'logout':home();logoutPrompt();break;case 'forgot-password':recoveryPage(false,q);break;case 'reset-password':recoveryPage(true,q);break;case 'sell':if(parts[1])await sellerForm(parts[1]==='custom',run);else sellerStart();break;case 'buy':navigate('/marketplace',true);return;case 'workspace':case 'dashboard':navigate('/account',true);return;case 'my-biddings':await myBiddingsPage(run);break;case 'my-properties':await myPropertiesPage(run);break;case 'account':await newAccountPage(q,run);break;case 'notifications':await notificationsPage(run);break;case 'admin':location.replace('/budapest-admin');return;case 'deals':if(parts[1])await(await import('/management.js')).renderDeals(managementContext(run),parts[1]);else{navigate('/account?tab=deals',true);return}break;case 'area':areaPage();break;case 'how-it-works':howPage();break;case 'about':aboutPage();break;case 'contact':contactPage();break;case 'privacy':privacyPage();break;case 'fees':feesPage();break;default:notFound()}}catch(e){if(run===routeRun)$('#app').innerHTML=pageTop('Please try again',esc(e.message))}if(run!==routeRun)return;document.title=(parts[0]?parts[0].replace(/-/g,' ').replace(/^./,c=>c.toUpperCase())+' | ':'')+'AuctionHouse.pk';if(!parts[0])document.title=siteContent.settings.page?.title||'AuctionHouse.pk — Property marketplace';if(parts[0]==='projects-info'&&parts[1])document.title=(siteContent.projectInfo||[]).find(p=>p.id===parts[1])?.title+' | AuctionHouse.pk';if(parts[0]==='listing'&&$('.listing-information h2'))document.title=$('.listing-information h2').textContent+' | AuctionHouse.pk';$('header').classList.remove('menu-open');window.scrollTo(0,0);updateNav();connectLive(parts[0]==='listing'?parts[1]:null);if(user)syncNotifications(true)}
async function init(){$('#year').textContent=new Date().getFullYear();if(location.hash.startsWith('#/'))history.replaceState({},'',location.hash.slice(1));document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.target.closest('[data-dismiss-notice]')||a.target||a.hasAttribute('download')||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const u=new URL(a.href,location.origin);if(u.origin===location.origin&&!u.pathname.startsWith('/api/')&&!u.hash){e.preventDefault();e.stopImmediatePropagation();navigate(u.pathname+u.search)}},true);addEventListener('pagehide',()=>{if(liveSource){liveSource.close();liveSource=null}clearInterval(auctionTimer);clearTimeout(auctionPoll)});addEventListener('popstate',()=>route());addEventListener('pageshow',e=>{if(e.persisted)route()});const results=await Promise.allSettled([api('/api/auth/me'),api('/api/auth/options'),api('/api/site')]);if(results[0].status==='fulfilled')user=results[0].value.user;if(results[1].status==='fulfilled')authOptions=results[1].value;if(results[2].status==='fulfilled')siteContent=results[2].value;updateNav();await syncNotifications(false);await route()}
init();

;
'use strict';
function ballotFlow(){return `<div class="ballot-flow sketch-flow"><svg viewBox="0 0 700 570" role="img" aria-labelledby="ballot-flow-title"><title id="ballot-flow-title">Apply for the LDA ballot, then sell or buy your file through AuctionHouse</title><defs><pattern id="flow-hatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><path d="M0 0V7" stroke="#22271d" stroke-width="1.3"/></pattern><marker id="flow-dot-arrow" markerWidth="9" markerHeight="9" refX="7" refY="4" orient="auto"><path d="M1 1L7 4L1 7" fill="none" stroke="#252a20" stroke-width="1.8"/></marker></defs><g class="sketch-shadow"><path d="M122 29Q114 19 135 19H565Q578 20 578 36L580 135Q579 151 562 151H132Q116 151 116 134Z"/><path d="M30 239L311 235L314 337L27 342Z"/><path d="M389 238L671 234L673 336L386 341Z"/><path d="M23 437L315 432L317 554L22 558Z"/><path d="M385 435L677 432L680 553L382 558Z"/></g><g class="flow-block-arrows"><path d="M241 155L263 174L225 211L243 213L204 228L210 185L218 202Z"/><path d="M474 157L450 174L486 213L469 213L509 230L505 187L495 202Z"/><path d="M160 350L180 351L179 396L199 394L168 423L138 394L159 396Z"/><path d="M519 350L540 351L540 396L559 393L529 423L498 394L519 396Z"/></g><path class="flow-dotted-link" d="M577 75H654V116" marker-end="url(#flow-dot-arrow)"/><g class="sketch-box"><path d="M128 13Q116 12 118 34L119 118Q117 138 136 138L560 136Q577 138 574 119L573 31Q573 13 557 13Z"/><path d="M35 229Q28 226 29 244L28 318Q27 330 44 329L302 327Q314 328 312 311L311 241Q311 226 298 228Z"/><path d="M395 228Q386 229 387 246L387 318Q387 330 403 328L660 327Q674 328 671 311L670 241Q670 226 655 227Z"/><path d="M31 430Q21 430 22 449L23 532Q22 546 42 544L302 541Q317 542 315 525L313 443Q313 427 298 428Z"/><path d="M393 430Q383 430 384 448L383 532Q384 545 401 544L662 541Q678 542 676 525L674 443Q674 428 659 428Z"/></g><g class="sketch-corners" fill="none"><path d="M130 45Q129 25 148 26M543 25Q562 26 561 45M39 454Q37 440 54 440M291 441Q303 441 302 455M399 455Q397 441 414 441M652 441Q665 442 664 456"/></g><g class="sketch-label"><text x="347" y="60"><tspan x="347">Apply for ballot on</tspan><tspan x="347" dy="37">LDA’s website</tspan></text><text x="170" y="270"><tspan x="170">Successful</tspan><tspan x="170" dy="31">applicant</tspan></text><text x="530" y="270"><tspan x="530">Unsuccessful</tspan><tspan x="530" dy="31">applicant</tspan></text><text x="169" y="469"><tspan x="169">Sell your</tspan><tspan x="169" dy="31">file here</tspan></text><text x="530" y="469"><tspan x="530">Buy a</tspan><tspan x="530" dy="31">file here</tspan></text></g><a href="${LDA}" target="_blank" rel="noopener" aria-label="Click for LDA’s website"><rect class="flow-link-box" x="341" y="112" width="347" height="45" rx="6"/><text class="flow-link-label" x="514" y="141">↗ Click for LDA’s website</text></a><a href="/sell" aria-label="Click to Sell"><rect class="flow-link-box" x="44" y="516" width="255" height="40" rx="5"/><text class="flow-link-label" x="172" y="542">↗ Click to Sell</text></a><a href="/marketplace" aria-label="Click to Buy"><rect class="flow-link-box" x="406" y="516" width="253" height="40" rx="5"/><text class="flow-link-label" x="532" y="542">↗ Click to Buy</text></a></svg></div>`}
const nov8Home=home;home=function(){nov8Home();const title=$('.hero h1');if(title)title.innerHTML=esc(title.textContent).replace(/opportunity/i,'<span class="opportunity-underline">opportunity</span>');const copy=$('.hero-copy');if(copy){title.insertAdjacentHTML('afterend','<p class="project-emphasis">Pine Axis Commercial - Pine Executive Residential</p>')}$('.hero-preview')?.remove();$('.hero-inner')?.insertAdjacentHTML('beforeend',ballotFlow())};
const nov8ProjectCard=projectCard;projectCard=function(p){return nov8ProjectCard(p).replace('</div></article>',`<a class="lda-apply-link" href="${LDA}" target="_blank" rel="noopener">Apply for ballot on LDA’s website ↗</a></div></article>`)};
siteDate=function(value,time=false){if(!value)return '—';const n=Number(value),d=new Date(Number.isFinite(n)?n:value),p=new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Karachi'}).formatToParts(d),part=t=>p.find(v=>v.type===t)?.value;return `${part('day')} ${part('month')}, ${part('year')}`+(time?' '+new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:true,timeZone:'Asia/Karachi'}).format(d).toUpperCase()+' PST':'')};
function shareIcon(l){return `<button type="button" class="share-icon" data-share-property="${esc(l.id)}" data-share-title="${esc(l.title)}" aria-label="Share property"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 16V2m-5 5 5-5 5 5M4 11v10h16V11"/></svg></button>`}
const nov8Heart=heart;heart=function(l){return `<div class="property-tools">${nov8Heart(l)}<div class="property-share-row">${landUse(l)}${shareIcon(l)}</div></div>`};
const nov8LandUse=landUse;landUse=function(l){return nov8LandUse(l).replace('class="land-use ','class="land-use land-pill ')};
function bindSharing(root=document){$$('[data-share-property]',root).forEach(b=>b.onclick=async e=>{e.preventDefault();e.stopPropagation();const url=location.origin+'/listing/'+encodeURIComponent(b.dataset.shareProperty),title=b.dataset.shareTitle;try{if(navigator.share){await navigator.share({title,text:title,url});return}const d=$('#dialog');if(d.open)d.close();d.className='confirm-dialog';$('#dialog-content').innerHTML='<h2 id="dialog-title">Share property</h2><p>Copy the link into any app, or share through WhatsApp.</p><input id="property-share-url" readonly value="'+esc(url)+'"><div class="btn-row"><button type="button" class="btn btn-black" id="copy-property-link">Copy link</button><a class="btn btn-outline" href="https://wa.me/?text='+encodeURIComponent(title+' '+url)+'" target="_blank" rel="noopener">WhatsApp</a></div>';$('#copy-property-link').onclick=async()=>{await navigator.clipboard.writeText(url);toast('Property link copied.')};d.showModal()}catch(error){if(error.name!=='AbortError')toast('You can copy this property link: '+url)}})}
const nov8Hearts=bindHearts;bindHearts=function(root=document){nov8Hearts(root);bindSharing(root)};
const nov8Card=auctionCard;auctionCard=function(l){return nov8Card(l).replace('<p>'+landText(l)+'</p>','').replace('<div class="auction-card-foot"><a','<div class="auction-card-foot"><a').replace(landUse(l)+'</div></div></article>','</div></div></article>').replace('<small class="listing-code">','<small class="listing-code">Property ID: ')};
const nov8Information=listingInformation;listingInformation=function(l){return nov8Information(l).replace('<p>'+landText(l)+'</p>','').replace('<small>'+esc(l.display_id||l.id)+'</small>','<small>Property ID: '+esc(l.display_id||l.id)+'</small>').replace('<strong>'+siteDate(l.starts_at)+'</strong>','<strong>'+siteDate(l.starts_at,true)+'</strong>').replace('<div class="land-use-row">'+landUse(l)+'</div>','')};
const nov8Facts=factsContent;factsContent=function(l,negotiation=false){const list=items=>'<ol>'+items.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ol>';return `<div class="terms-copy"><h2>${negotiation?'Terms and Conditions for Negotiation':'Facts for Auction'}</h2>${list(negotiation?l.negotiation_terms:l.facts)}${negotiation?'':'<h2>Terms and Conditions for Auction</h2>'+list(l.terms)+'<p>A bid in the final five minutes extends bidding until five minutes remain.</p>'}<p>Price mode: ${esc(l.unit_mode)}. ${negotiation?'Negotiation interval: '+cash(l.negotiation_interval)+'. Seller response time: '+l.negotiation_time/60000+' minutes.':'Bid interval: '+cash(l.interval1)+'.'}</p>${l.showTokenEntry?'<p class="token-entry-notice">Refundable Token Money required: <strong>'+cash(l.participation_deposit||0)+'</strong>. This amount is reserved from your available balance when you enter for the first time.</p>':''}</div>`};
function readFacts(l){const d=$('#dialog');if(d.open)d.close();d.className='terms-dialog';$('#dialog-content').innerHTML='<h2 id="dialog-title">Facts and Terms</h2><div class="terms-scroll">'+factsContent(l)+'</div>';d.showModal()}
async function propertyBid(r,amount,done){if(!authGate(listingURL(r.listing)))return;if(!r.auctionTermsAccepted){termsModal({...r.listing,showTokenEntry:!r.tokenDisclosed},false,null,done);return}confirmAction('Confirm your bid',cash(amount)+mode(r.listing)+' for '+r.listing.title+'.',async()=>{await api('/api/listings/'+r.listing.id+'/bid',{amount,version:r.listing.version});await done();toast('Your bid was placed.')})}
listingPage=async function(id,view,run){try{let r=await api('/api/listings/'+id);if(run!==routeRun)return;if(view==='bid'&&!authGate('/listing/'+id+'/bid'))return;let l=r.listing;const showBids=view==='bid'||r.bidState!=='none';$('#app').innerHTML=pageTop(esc(l.title))+`<div class="listing-top-tools"><span id="my-bidder-code"></span></div><section class="section listing-layout"><div>${gallery(l)}${listingInformation(l)}</div><aside class="panel bidding-panel" data-auction-end="${l.ends_at}" data-auction-start="${l.starts_at}" data-holding-until="${l.starts_at+l.holding_period}"><h2>Bidding closes in</h2><p class="countdown" data-countdown="${l.ends_at}"></p><p id="exact-closing"></p><small class="pakistan-now"></small><p id="live-connection-status" role="status"></p><p id="bid-standing" role="status"></p><p id="listing-status"></p><div class="last-bid" aria-live="polite">Highest Bid <strong id="last-bid-amount"></strong></div>${!r.isSeller?(showBids?'<h3>Place your Bid'+esc(mode(l))+'</h3><div class="bid-buttons">'+[1,2,3].map(i=>'<button class="btn btn-charcoal" data-bid></button>').join('')+'</div>':'<button class="btn btn-accent full-button" id="enter-bidding">Enter Bidding</button>'): '<a class="btn btn-black full-button" href="/my-properties">Click to Manage this Property</a>'}<button class="btn btn-green full-button" id="enter-negotiation" hidden></button><button id="poke-seller" class="btn btn-outline full-button" hidden>Remind seller to accept your bid</button><div class="bid-history"><h2>Bid history</h2><div id="bid-history-table"></div></div><button class="btn btn-outline full-button" id="read-facts">Facts and Terms</button></aside></section>`;const update=state=>{if(state.listing.version<r.listing.version)return;r=state;l=r.listing;$('.bidding-panel').dataset.auctionEnd=l.ends_at;$('.bidding-panel [data-countdown]').dataset.countdown=l.ends_at;const open=l.status==='active'&&l.ends_at>Date.now()&&l.starts_at<=Date.now();$('#last-bid-amount').textContent=cash(l.current_price);$('#current-bid-display').innerHTML=currentBid(l);$('#bid-history-table').innerHTML=historyTable(r);$('#exact-closing').textContent='Closes '+siteDate(l.ends_at,true);$('.pakistan-now').textContent='Current Pakistan time: '+siteDate(Date.now(),true);$('#listing-closes-at').textContent=siteDate(l.ends_at,true);$('#my-bidder-code').textContent=r.myBidder?'Bidding ID: '+r.myBidder.bidder_code:'';$('#bid-standing').textContent=r.bidState==='winning'?'You are highest bidder till now':r.bidState==='outbid'?'You are not highest bidder, place higher bid':'';$('#bid-standing').className=r.bidState;$('#listing-status').textContent=open?'':l.status==='agreed'?'Deal accepted.':l.status==='active'&&l.starts_at>Date.now()?'Bidding opens '+siteDate(l.starts_at,true):'Bidding closed.';$$('[data-bid]').forEach((b,i)=>{b.textContent=cash(l.current_price+l.interval1*(i+1));b.hidden=r.bidState==='winning';b.disabled=!open||r.isSeller||r.bidState==='winning';b.onclick=()=>propertyBid(r,l.current_price+l.interval1*(i+1),refresh)});const bidHeading=$('.bidding-panel h3');if(bidHeading)bidHeading.hidden=r.bidState==='winning';const poke=$('#poke-seller');poke.dataset.pokeAfter=r.sellerReminderAvailable&&r.bidState==='winning'&&r.bids.length?String(r.bids[0].created_at+3600000):'0';poke.hidden=!r.sellerReminderAvailable||r.bidState!=='winning'||!r.bids.length||Date.now()-r.bids[0].created_at<3600000;poke.onclick=async()=>{try{await api('/api/listings/'+id+'/poke',{});toast('Seller notified.')}catch(e){toast(e.message)}};const neg=$('#enter-negotiation'),mine=r.negotiations.find(n=>['requested','approved','buyer_turn','seller_turn','expired'].includes(n.status));neg.hidden=!open||r.isSeller||!r.negotiationAvailable&&!mine;neg.textContent=mine?.status==='requested'?'Negotiation request pending':mine?'Enter negotiation with the Seller':l.negotiation_enabled?'Enter negotiation with the Seller':'Request Seller for negotiation';neg.disabled=mine?.status==='requested';neg.onclick=()=>{if(!authGate(listingURL(l)))return;if(mine&&mine.status!=='requested'){navigate(listingURL(l)+'/negotiation/'+mine.id);return}termsModal({...l,showTokenEntry:!r.tokenDisclosed},!!l.negotiation_enabled,null,async()=>{if(l.negotiation_enabled){const n=await api('/api/listings/'+id+'/start-negotiation',{});navigate(listingURL(l)+'/negotiation/'+n.id)}else{await api('/api/listings/'+id+'/request-negotiation',{});await refresh();toast('Your private request was sent to the seller.')}})}};const refresh=async()=>{const state=await api('/api/listings/'+id);if(run===routeRun&&$('#bid-history-table'))update(state)};currentListingRefresh=refresh;$('#read-facts').onclick=()=>readFacts(l);$('#enter-bidding')?.addEventListener('click',()=>termsModal({...l,showTokenEntry:!r.tokenDisclosed}));bindGallery();bindHearts();update(r);startClocks();if(view==='facts')readFacts(l)}catch(error){if(run===routeRun)$('#app').innerHTML=pageTop('Property unavailable',esc(error.message))}};
negotiationPage=async function(listingId,id,run){if(!authGate('/listing/'+listingId+'/negotiation/'+id))return;try{let r=await api('/api/negotiations/'+id),n=r.negotiation,l=r.listing;if(run!==routeRun)return;$('#app').innerHTML=pageTop(esc(l.title),'Private negotiation')+`<section class="section listing-layout"><div>${gallery(l)}${listingInformation(l)}</div><aside class="panel negotiation-panel"><h2>Private negotiation</h2><p class="countdown" data-countdown="${n.deadline}"></p><p id="neg-status"></p><p id="neg-current"></p><label>Your offer (PKR)<input type="number" id="neg-input" step="${l.negotiation_interval/100}" min="${Math.ceil(l.starting_price*.4)/100}" max="${(l.starting_price-l.negotiation_interval)/100}"></label><div class="neg-controls"><button class="btn btn-outline" id="neg-minus">−</button><button class="btn btn-outline" id="neg-plus">+</button><button class="btn btn-accent" id="submit-offer">Submit offer</button><button class="btn btn-black" id="accept-offer">Accept current offer</button><button class="btn btn-outline" id="neg-ping">Remind other party</button></div><p>Offers must change in multiples of ${cash(l.negotiation_interval)}, including when reopening. Offers must be at least 40% and less than 100% of the starting price. Your next buyer offer cannot decrease; your next seller offer cannot increase. An expired negotiation can reopen with an improved offer.</p><h3>Negotiation history</h3><ol id="neg-history"></ol></aside></section>`;const update=state=>{r=state;n=r.negotiation;const expired=n.status==='expired',turn=r.isSeller?n.status==='seller_turn':['approved','buyer_turn'].includes(n.status);$('#neg-status').textContent=n.status.replace(/_/g,' ');$('#neg-current').textContent='Current offer: '+cash(n.amount);$('.negotiation-panel [data-countdown]').dataset.countdown=n.deadline;$('#submit-offer').disabled=!expired&&!turn;$('#submit-offer').textContent=expired?'Reopen with improved offer':'Submit offer';$('#accept-offer').hidden=!turn||expired;const suggested=suggestedNegotiationOffer(r),range=negotiationOfferRange(r);$('#neg-input').min=String((range.anchor+range.min*range.step)/100);$('#neg-input').max=String((range.anchor+range.max*range.step)/100);$('#neg-input').step=String(l.negotiation_interval/100);$('#neg-input').value=suggested===null?'':suggested/100;if(suggested===null)$('#submit-offer').disabled=true;$('#neg-history').innerHTML=r.history.map(h=>'<li>'+esc(h.actor)+' · '+esc(h.action)+' · '+cash(h.amount)+' · '+siteDate(h.created_at,true)+'</li>').join('')};const refresh=async()=>{const state=await api('/api/negotiations/'+id);if(run===routeRun&&$('#neg-history'))update(state)};currentListingRefresh=refresh;const amount=()=>Math.round(Number($('#neg-input').value)*100);$('#neg-minus').onclick=()=>$('#neg-input').value=adjustNegotiationOffer(r,amount(),-1)/100;$('#neg-plus').onclick=()=>$('#neg-input').value=adjustNegotiationOffer(r,amount(),1)/100;const act=action=>confirmAction(action==='agree'?'Accept this offer?':'Confirm private offer',cash(action==='agree'?n.amount:amount()),async()=>{await api('/api/negotiations/'+id+'/'+action,{amount:amount(),version:n.version});await refresh()});$('#submit-offer').onclick=()=>act(n.status==='expired'?'reopen':r.isSeller?'counter':'offer');$('#accept-offer').onclick=()=>act('agree');$('#neg-ping').onclick=async()=>{try{await api('/api/negotiations/'+id+'/ping',{});toast('Private reminder sent.')}catch(e){toast(e.message)}};update(r);bindGallery();bindHearts();startClocks()}catch(e){$('#app').innerHTML=pageTop('Private negotiation',esc(e.message))}};
let nov8Audio;document.addEventListener('pointerdown',()=>{try{nov8Audio=new (window.AudioContext||window.webkitAudioContext)();nov8Audio.resume()}catch{}},{once:true});function noticeTone(){try{if(nov8Audio?.state!=='running')return;const tone=nov8Audio.createOscillator(),gain=nov8Audio.createGain();tone.frequency.value=660;gain.gain.setValueAtTime(.06,nov8Audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,nov8Audio.currentTime+.2);tone.connect(gain);gain.connect(nov8Audio.destination);tone.start();tone.stop(nov8Audio.currentTime+.21)}catch{}}
function notificationDetails(n){return `<small>Property: ${esc(n.property_title||'Not related to a property')} · Property ID: ${esc(n.property_id||'—')} · Bidding ID: ${esc(n.bidding_id||'Not assigned')}</small>`}
syncNotifications=async function(showNew=true){if(!user||noticeSync)return;noticeSync=true;try{const r=await api('/api/notifications?after='+(noticesInitialized?noticeCursor:0));if(showNew&&noticesInitialized)for(const n of [...r.notifications].reverse()){const key=n.kind==='bid'?'bid:'+n.listing_id:'notice:'+n.id;let card=$$('#notification-toasts .bid-notification').find(e=>e.dataset.noticeKey===key);if(!card){card=document.createElement('div');card.className='bid-notification';card.dataset.noticeKey=key;$('#notification-toasts').append(card)}card.innerHTML='<a href="'+esc(n.url)+'"><strong>'+esc(n.title)+'</strong><p>'+esc(n.body)+'</p>'+notificationDetails(n)+'</a><button type="button" data-dismiss-notice aria-label="Dismiss notification">×</button>';$('button',card).onclick=e=>{e.preventDefault();e.stopImmediatePropagation();clearTimeout(card.dismissTimer);card.remove()};clearTimeout(card.dismissTimer);card.dismissTimer=setTimeout(()=>card.remove(),6000);noticeTone()}noticeCursor=Math.max(noticeCursor,...r.notifications.map(n=>n.id),0);noticesInitialized=true;$$('[data-notification-count]').forEach(el=>el.textContent=r.unread?String(r.unread):'');if(location.pathname==='/notifications'&&r.notifications.length)await notificationsPage(routeRun,false);await updateSectionStars()}catch{}finally{noticeSync=false}};
notificationsPage=async function(run,mark=true){if(!authGate('/notifications'))return;const r=await api('/api/notifications');if(run!==routeRun)return;$('#app').innerHTML=pageTop('Notifications')+'<section class="section notifications-list">'+(r.notifications.length?r.notifications.map(n=>'<article class="panel notification-item '+(n.read_at?'':'unread')+'"><a href="'+esc(n.url)+'"><h3>'+esc(n.title)+'</h3><p>'+esc(n.body)+'</p>'+notificationDetails(n)+'<small>'+siteDate(n.created_at,true)+'</small></a><button class="btn btn-outline" data-delete-notification="'+n.id+'">Delete</button></article>').join(''):'<div class="panel">No notifications yet.</div>')+'</section>';$$('[data-delete-notification]').forEach(b=>b.onclick=()=>confirmAction('Delete this notification?','This removes the notification from your inbox.',async()=>{await api('/api/notifications',{remove:Number(b.dataset.deleteNotification),confirm:true});await notificationsPage(run,false)}));if(mark&&r.notifications.length){await api('/api/notifications',{before:Math.max(...r.notifications.map(n=>n.id))});$$('[data-notification-count]').forEach(e=>e.textContent='')}};
function sellerFeatures(){return '<fieldset class="field full" data-field="features" id="s-features"><legend>Salient features</legend>'+['Park facing','Corner','Main road','Main Boulevard','Near Mosque'].map(f=>'<label class="feature-check"><input type="checkbox" data-feature name="features" value="'+f+'"> '+f+'</label>').join('')+'</fieldset>'}
const nov8Seller=sellerForm;sellerForm=async function(custom,run){await nov8Seller(custom,run);if(run!==routeRun||!$('#seller-form'))return;if(custom&&!new URLSearchParams(location.search).get('edit'))for(const [key,value]of Object.entries(siteContent.settings.general||{})){const el=$('#s-'+key);if(el&&/^\s*(?:\d+[.)]\s*)?$/.test(el.value))el.value=numberedText(value)}const q=new URLSearchParams(location.search);if(q.get('edit')){const l=(await api('/api/listings/'+q.get('edit'))).listing;$$('[data-feature]').forEach(b=>b.checked=l.features.includes(b.value))}const token=document.createElement('p');token.className='token-notice';$('#seller-form').prepend(token);const update=()=>{const p=siteContent.projects.find(p=>p.id===$('#s-project')?.value);token.textContent=custom?'Your property shall be reviewed after submission. Auction House will decide and notify you of its Refundable Token Money.':'Refundable Token Money required: '+cash(p?.deposit||0)+'. You need this available balance to submit.'};$('#s-project')?.addEventListener('change',update);update();$('#listing-documents').required=false};
async function updateSectionStars(){if(!user)return;try{const r=await api('/api/activity');$$('[data-section-star]').forEach(e=>e.textContent=r.badges[e.dataset.sectionStar]?' ★':'')}catch{}}
const nov8Nav=updateNav;updateNav=function(){nov8Nav();for(const cls of ['biddings-nav','properties-nav'])$('.nav-actions .'+cls).hidden=!user;const mobile=$('.mobile-account-links');if(mobile)mobile.innerHTML=$$('.nav-actions>.biddings-nav,.nav-actions>.properties-nav,.nav-actions>.account-nav,.nav-actions>.login-nav,.nav-actions>.register-nav').filter(el=>!el.hidden).map(el=>el.outerHTML).join('');if(user)updateSectionStars()};
async function bindSellerDrafts(run){for(const holder of $$('[data-seller-listing]')){const r=await api('/api/listings/'+holder.dataset.sellerListing),l=r.listing;if(run!==routeRun)return;if(l.review_state==='awaiting_token'){holder.insertAdjacentHTML('afterbegin','<button class="btn btn-accent" data-fund-token>Reserve Refundable Token Money and publish</button>');$('[data-fund-token]',holder).onclick=()=>confirmAction('Reserve Refundable Token Money?',cash(l.participation_deposit),async()=>{await api('/api/listings/'+l.id+'/fund-token',{version:l.version});await myPropertiesPage(run)})}if(l.admin_draft){const draft=l.admin_draft;holder.insertAdjacentHTML('afterbegin','<div class="draft-review"><h3>Proposed changes from Auction House</h3><p>'+esc(l.draft_note)+'</p><dl>'+Object.entries(draft.after).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd><del>'+esc(draftValue(k,draft.before[k]))+'</del><strong class="changed-value">'+esc(draftValue(k,v))+'</strong></dd>').join('')+'</dl><label>Reason if rejecting<textarea data-draft-reason></textarea></label><button class="btn btn-black" data-draft-response="accept-draft">Accept changes</button><button class="btn btn-outline" data-draft-response="reject-draft">Reject changes</button></div>');$$('[data-draft-response]',holder).forEach(b=>b.onclick=()=>confirmAction(b.dataset.draftResponse==='accept-draft'?'Accept proposed changes?':'Reject proposed changes?','Your response is recorded and returned to Auction House.',async()=>{await api('/api/listings/'+l.id+'/'+b.dataset.draftResponse,{version:l.version,note:$('[data-draft-reason]',holder).value});await myPropertiesPage(run)}))}}}
const nov8Clocks=startClocks;startClocks=function(){nov8Clocks();clearInterval(window.nov8Clock);window.nov8Clock=setInterval(()=>{$$('.pakistan-now').forEach(e=>e.textContent='Current Pakistan time: '+siteDate(Date.now(),true));const poke=$('[data-poke-after]');if(poke&&Number(poke.dataset.pokeAfter))poke.hidden=Date.now()<Number(poke.dataset.pokeAfter);const panel=$('[data-holding-until]');if(panel&&Date.now()>=Number(panel.dataset.holdingUntil)&&!panel.dataset.holdingChecked){panel.dataset.holdingChecked='1';currentListingRefresh?.()}},1000)};

function draftValue(key,value){if(['starting_price','interval1','negotiation_interval','participation_deposit'].includes(key))return cash(Number(value));if(['starts_at','ends_at'].includes(key))return siteDate(Number(value),true);try{const list=JSON.parse(value);if(Array.isArray(list))return list.join('\n')}catch{}return value}

