'use strict';
function biddingSummaryCard(l){return auctionCard(l).replace(/<div class="auction-card-foot">[\s\S]*?<\/div><\/div><\/article>$/,`<div class="auction-card-foot"><a class="btn btn-black bidding-page-entry" href="${listingURL(l)}">Enter Bidding Page</a></div></div></article>`)}
function sellerPropertyCard(l){const buttons=`<div class="property-actions">${['pending','rejected'].includes(l.status)?`<a class="btn property-edit" href="/sell/${l.project==='custom'?'custom':'project'}?edit=${esc(l.id)}">Edit and resubmit</a>`:''}${l.status==='active'?`<button class="btn property-negotiate" disabled data-enable-neg="${esc(l.id)}">${l.negotiation_enabled?'Disable':'Enable'} negotiation</button>`:''}${['pending','active'].includes(l.status)?`<button class="btn property-withdraw" disabled data-withdraw="${esc(l.id)}">Withdraw listing</button>`:''}</div>`;return auctionCard(l).replace('<strong>'+cash(l.starting_price)+'</strong>','<strong>'+cash(l.starting_price)+'</strong>'+buttons)}
async function newAccountPage(q,run){const old=q.get('tab');if(['bids','listings'].includes(old)){navigate(old==='bids'?'/my-biddings':'/my-properties',true);return}if(old==='searches')q.set('tab','favorites');await renderAccountArea(q,run,'account')}
async function myBiddingsPage(run){await renderAccountArea(new URLSearchParams(),run,'bids');if(run!==routeRun||!user)return;await api('/api/activity',{section:'bids'});await updateSectionStars();startClocks()}
async function myPropertiesPage(run){await renderAccountArea(new URLSearchParams(),run,'listings');if(run!==routeRun||!user)return;await bindSellerDrafts(run);await api('/api/activity',{section:'properties'});await updateSectionStars();startClocks()}
async function reloadPersonalSection(q,run){if(location.pathname==='/my-properties')return myPropertiesPage(run);if(location.pathname==='/my-biddings')return myBiddingsPage(run);return newAccountPage(q,run)}
function negotiationOfferRange(state){const n=state.negotiation,l=state.listing,expired=n.status==='expired',own=state.isSeller?n.sellerLast:n.buyerLast,anchor=l.starting_price,step=l.negotiation_interval;let low=Math.ceil(l.starting_price*.4),high=l.starting_price-step;if(own!==null&&own!==undefined){if(state.isSeller)high=Math.min(high,own);else low=Math.max(low,own)}if(expired){const previous=own??n.amount;if(state.isSeller)high=Math.min(high,previous-1);else low=Math.max(low,previous+1)}return {anchor,step,min:Math.ceil((low-anchor)/step),max:Math.floor((high-anchor)/step)}}
function suggestedNegotiationOffer(state){const range=negotiationOfferRange(state),direction=state.negotiation.status==='expired'?(state.isSeller?-1:1):(state.isSeller?1:-1);const relative=(state.negotiation.amount-range.anchor)/range.step;let index=direction>0?Math.floor(relative)+1:Math.ceil(relative)-1;index=Math.max(range.min,Math.min(range.max,index));if(range.anchor+index*range.step===state.negotiation.amount)index+=direction;if(index<range.min||index>range.max)return null;return range.anchor+index*range.step}
function adjustNegotiationOffer(state,amount,direction){const range=negotiationOfferRange(state),relative=(amount-range.anchor)/range.step;let index=direction>0?Math.floor(relative)+1:Math.ceil(relative)-1;if(index===0)index+=direction;if(index<range.min||index>range.max){toast('No further interval-sized offer is available within your limits.');return amount}return range.anchor+index*range.step}

