const nov9Home=home;home=function(){nov9Home();const intro=$('.hero-copy>p:not(.project-emphasis):not(.open-status)');if(intro)intro.classList.add('hero-intro');const emphasis=$('.project-emphasis');if(emphasis){emphasis.innerHTML=[['pine-axis','Pine Axis Commercial'],['pine-executive','Pine Executive Residential']].filter(([id])=>(siteContent.projectInfo||[]).some(p=>p.id===id)).map(([id,label])=>'<a href="/projects-info/'+id+'">'+label+'</a>').join('');if(intro)intro.insertAdjacentElement('afterend',emphasis)}};
const nov9CurrentBid=currentBid;currentBid=function(l){return l.status==='pending'?'<span class="pending-bid">Listing pending for review</span>':nov9CurrentBid(l)};
function projectInfoNav(){const items=siteContent.projectInfo||[];$$('.projects-info-nav').forEach(nav=>{nav.hidden=!items.length;$('.project-info-menu',nav).innerHTML=items.map(p=>'<a href="/projects-info/'+esc(p.id)+'">'+esc(p.tab_name)+'</a>').join('')})}
