function projectTextHTML(text){return String(text).split(/\n\s*\n/).filter(Boolean).map(paragraph=>'<p>'+paragraph.split(/(\[[^\]\n]+\]\(https?:\/\/[^\s)]+\))/g).map(part=>{const m=part.match(/^\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)$/);return m?'<a href="'+esc(m[2])+'" target="_blank" rel="noopener noreferrer">'+esc(m[1])+'</a>':esc(part).replace(/\n/g,'<br>')}).join('')+'</p>').join('')}
function projectInfoPage(id){const items=siteContent.projectInfo||[];if(!id){$('#app').innerHTML=pageTop('Projects Info')+'<section class="section project-info-index">'+items.map(p=>'<a class="panel" href="/projects-info/'+esc(p.id)+'"><h2>'+esc(p.title)+'</h2><p>View project information →</p></a>').join('')+'</section>';return}const p=items.find(p=>p.id===id);if(!p){notFound();return}const paragraphs=p.content.split(/\n\s*\n/).filter(Boolean),images=p.images||[],image=i=>'<figure class="project-info-image image-'+esc(i.align)+'"><img src="'+esc(i.url)+'" alt="'+esc(i.caption||p.title)+'" width="1000" height="700" loading="lazy">'+(i.caption?'<figcaption>'+esc(i.caption)+'</figcaption>':'')+'</figure>',at=position=>images.filter(i=>i.position===position).map(image).join('');$('#app').innerHTML=pageTop(esc(p.title))+'<article class="section project-info-content prose">'+at(0)+paragraphs.map((text,i)=>projectTextHTML(text)+at(i+1)).join('')+images.filter(i=>i.position<0||i.position>paragraphs.length).map(image).join('')+'</article>';document.title=p.title+' | AuctionHouse.pk'}

// Coalesce pushes. These update the current view, never reload the document or navigate.
let liveViewBusy=false,liveViewAgain=false;
async function refreshVisibleData(){if(liveViewBusy){liveViewAgain=true;return}liveViewBusy=true;const run=routeRun,path=location.pathname;try{if(currentListingRefresh)await currentListingRefresh();if(user)await syncNotifications(true);if(run!==routeRun)return;if(['/account','/my-biddings','/my-properties'].includes(path)){if(!$('#dialog').open&&!document.activeElement?.closest('form,.draft-review')&&!(path==='/account'&&new URLSearchParams(location.search).get('tab')==='settings')){await renderAccountArea(new URLSearchParams(location.search),run,path==='/my-biddings'?'bids':path==='/my-properties'?'listings':'account');if(path==='/my-properties')await bindSellerDrafts(run)}}else if(path==='/marketplace'){const q=new URLSearchParams(location.search);if(!q.has('project'))q.set('project','all');const r=await api('/api/listings?'+q);if(run!==routeRun||!$('#market-results'))return;const old=$('#market-results');old.innerHTML=r.listings.length?'<div class="auction-grid">'+r.listings.map(auctionCard).join('')+'</div>':'<div class="panel">No active listings match these filters.</div>';if(r.pages>1){const pageLink=n=>{const p=new URLSearchParams(q);p.set('page',n);return '/marketplace?'+p};old.insertAdjacentHTML('beforeend','<nav class="results-pagination" aria-label="Listing results pages">'+(r.page>1?'<a class="btn btn-outline" href="'+esc(pageLink(r.page-1))+'">Previous</a>':'')+'<span>'+r.total+' properties · Page '+r.page+' of '+r.pages+'</span>'+(r.page<r.pages?'<a class="btn btn-outline" href="'+esc(pageLink(r.page+1))+'">Next</a>':'')+'</nav>')}bindHearts();startClocks()}}catch{}finally{liveViewBusy=false;if(liveViewAgain){liveViewAgain=false;queueMicrotask(refreshVisibleData)}}}
async function refreshSiteData(onlyChanged=false){const run=routeRun;try{const next=await api('/api/site');if(onlyChanged&&JSON.stringify(next)===JSON.stringify(siteContent))return;siteContent=next;updateNav();if(run!==routeRun)return;if(location.pathname==='/')home();else if(location.pathname.startsWith('/projects-info'))projectInfoPage(location.pathname.split('/')[2]);else if(location.pathname==='/about')aboutPage();else if(location.pathname==='/how-it-works')howPage();else if(location.pathname==='/contact')contactPage();else if(location.pathname==='/marketplace')await marketPage(new URLSearchParams(location.search),run)}catch{}}
connectLive=function(listingId){if(liveSource)liveSource.close();const channels=['?scope=site',...(listingId?['?listing='+encodeURIComponent(listingId)]:[]),...(user?['']:[])],connections=new Set(),timers=new Set();let closed=false;const debounces={};const schedule=kind=>{clearTimeout(debounces[kind]);debounces[kind]=setTimeout(()=>kind==='site'?refreshSiteData():refreshVisibleData(),100)};for(const channel of channels){let connected=false;const connect=()=>{if(closed)return;const socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/api/live'+channel);connections.add(socket);socket.onopen=()=>{if(connected){if(channel==='?scope=site')refreshSiteData();else refreshVisibleData()}connected=true};socket.onmessage=e=>{if(e.data==='pong')return;let event;try{event=JSON.parse(e.data)}catch{return}if(event.initial){if(channel==='?scope=site')refreshSiteData(true);else schedule('data');return;}if(event.type==='site')schedule('site');else if(channel!=='?scope=site')schedule('data');else if(event.type==='catalogue'&&location.pathname==='/marketplace')schedule('data')};socket.onclose=()=>{connections.delete(socket);if(!closed){const timer=setTimeout(()=>{timers.delete(timer);connect()},3000+Math.random()*2000);timers.add(timer)}};socket.onerror=()=>socket.close()};connect()}liveSource={close(){closed=true;Object.values(debounces).forEach(clearTimeout);connections.forEach(s=>{s.onclose=null;s.close()});timers.forEach(clearTimeout)}}};

setInterval(()=>{const panel=$('[data-auction-start]');if(panel&&!panel.dataset.openingUpdated&&Number(panel.dataset.auctionStart)<=Date.now()){panel.dataset.openingUpdated='1';currentListingRefresh?.()}},1000);
